{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "금연구역이 아닌 곳이 모두 흡연구역인지 여부",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "금연구역이 아닌 곳이 모두 흡연구역인 것은 아닙니다. 이 조례는 시장이 제5조제1항 각 호의 장소를 금연구역으로 지정할 수 있다고 정하고, 제5조제4항에서 지정된 금연구역에서는 흡연을 해서는 안 된다고 규정할 뿐, 금연구역이 아닌 모든 장소를 흡연구역으로 정하지는 않습니다. 또한 제8조제1항은 금연구역으로 지정된 장소의 소유자·점유자 또는 관리자가 그 구역 내에 흡연구역을 설치·운영할 수 있다고 하여, 흡연구역은 금연구역 안에서도 설치·운영될 수 있는 별도의 구역임을 보여줍니다.",
          "b_ids": "금연:제5조제1항,금연:제5조제1항제1호,금연:제5조제1항제2호,금연:제5조제1항제3호,금연:제5조제1항제5호,금연:제5조제1항제6호,금연:제5조제1항제7호,금연:제5조제1항제9호,금연:제5조제1항제10호,금연:제5조제1항제11호,금연:제5조제1항제12호,금연:제5조제4항,금연:제8조제1항"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "담배 연기로 인한 피해를 참아야 하는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "담배 연기로 인한 피해를 그냥 참아야 하는 것은 아닙니다. 제4조제1항은 시장이 시민의 건강보호를 위하여 금연환경을 조성하고 간접흡연으로 인한 피해를 방지하는 데 필요한 조치를 해야 한다고 정하고 있습니다. 제2조제3호는 간접흡연을 비흡연자가 흡연 시 발생하는 유해 물질에 노출되는 것으로 정의하며, 담배 연기에 직접 노출되는 2차 흡연과 흡착된 유해 물질이 다시 배출되는 3차 흡연을 모두 포함한다고 규정합니다.",
          "b_ids": "금연:제4조제1항,금연:제2조제3호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
